import requests
import re

# Try to access the Collins dictionary page with different headers
url = 'https://www.collinsdictionary.com/dictionary/spanish-english/caminata'
headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36',
    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
    'Accept-Language': 'en-US,en;q=0.5',
    'Accept-Encoding': 'gzip, deflate',
    'Connection': 'keep-alive',
    'Upgrade-Insecure-Requests': '1',
}

try:
    response = requests.get(url, headers=headers, timeout=10)
    print(f'Status code: {response.status_code}')

    if response.status_code == 200:
        content = response.text
        # Look for any mention of 1994
        year_matches = re.findall(r'\b1994\b', content)
        if year_matches:
            print(f'Found 1994 mentioned {len(year_matches)} times')
            # Find sentences around 1994
            sentences = re.findall(r'[.!?][^.!?]*1994[^.!?]*[.!?]', content)
            for i, sentence in enumerate(sentences):
                print(f'Sentence {i+1}: {sentence.strip()}')
        else:
            print('No 1994 found in the page')

        # Look for example sentences
        examples = re.findall(r'Example[s]?:[^.]*[.!?]', content)
        if examples:
            print(f'Found {len(examples)} example mentions')
            for i, example in enumerate(examples[:3]):
                print(f'Example {i+1}: {example.strip()}')
    else:
        print(f'Failed to access page: {response.status_code}')
        print('Response headers:', response.headers)

except Exception as e:
    print(f'Error: {e}')
""}

